-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "esMX" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.era.paladin.holy.Name"] = "Sagrado"
L["rm.era.paladin.holy.Description"] = "Sanación en grupo con el árbol Sagrado, desde el nivel 10. Actúa sobre tu objetivo amistoso y elige la sanación según la salud que le falte: Limpiar o Purificar, Choque Sagrado mientras te mueves, Luz Sagrada de rango máximo por debajo del 40 %, Luz Sagrada de rango 6 por debajo del 65 %, Destello de Luz de rango máximo por debajo del 85 % y Destello de Luz de rango 4 por debajo del 95 %. Con un enemigo al alcance cuerpo a cuerpo: Sello de sabiduría y, fuera de bandas, Sentencia. Recordatorios: Aura de concentración o de devoción, Bendición de sabiduría, y Favor divino e Imposición de manos para un objetivo con muy poca salud. Elegir a quién sanar queda a tu cargo; los paladines Sagrado que juegan en solitario reciben la rotación integrada de Reprensión."
L["rm.era.paladin.protection.Name"] = "Protección"
L["rm.era.paladin.protection.Description"] = "Tanqueo del nivel 1 al 60, elegida por Furia recta o por el árbol de Protección. Sello de Rectitud (Sello de sabiduría cuando el maná baja del 40 %), Escudo Sagrado y Sentencia para iniciar el combate, Escudo Sagrado siempre activo, Consagración y Cólera Sagrada (no-muertos y demonios) cuando dos o más enemigos luchan contra ti; si no, Sentencia del cruzado una vez, y después Sentencia y Consagración con maná de sobra, y Exorcismo contra no-muertos y demonios. Recordatorios: Furia recta, Aura de devoción, Salvaguardia, Reyes o Poderío, e Imposición de manos cuando estás a punto de morir. Las provocaciones, el uso repetido de Bendición de reyes y los rangos de hechizos quedan a tu cargo."
L["rm.era.paladin.protection.icyveins.Name"] = "Protección, Sello de sabiduría (Icy Veins)"
L["rm.era.paladin.protection.icyveins.Description"] = "El tanqueo de banda de Icy Veins con la rotación de Sabiduría de Wowhead, una alternativa a la rotación integrada de Protección recomendada, desactivada de forma predeterminada: actívala y desactiva aquella, o aumenta su prioridad. Mantiene activo Sello de sabiduría y lo juzga siempre que al objetivo le falte Sentencia de sabiduría (si no, solo juzga para iniciar el combate); Escudo Sagrado, Consagración cada vez que esté disponible, Cólera Sagrada contra grupos de no-muertos y demonios, Exorcismo, y Bendición de reyes superior como relleno de amenaza en banda. Los mismos recordatorios que la rotación integrada recomendada."
L["rm.era.paladin.retribution.Name"] = "Reprensión"
L["rm.era.paladin.retribution.Description"] = "Reprensión cuerpo a cuerpo del nivel 1 al 60, y la opción predeterminada para cualquier paladín al que no se ajuste ninguna otra rotación integrada. Contra élites y en combates largos fuera de bandas pone Sello del cruzado y lo juzga una vez; si no, mantiene activo un sello (Orden con un arma de 3,5 segundos o más lenta; si no, Rectitud), Exorcismo y Cólera Sagrada contra no-muertos y demonios, Martillo de cólera, Sentencia cada vez que esté disponible, y Consagración mientras Venganza esté activa o contra dos o más enemigos cercanos. Recordatorios: Aura de santidad, de reprensión o de devoción, Bendición de sabiduría en solitario o de poderío en grupo, una sanación entre combates, y Escudo divino, Protección divina o Imposición de manos cuando estás a punto de morir. La alternancia de sellos es otra rotación integrada; la elección de objetivo y el posicionamiento quedan a tu cargo."
L["rm.era.paladin.retribution.twist.Name"] = "Reprensión, alternancia de sellos"
L["rm.era.paladin.retribution.twist.Description"] = "Desactivada por defecto; actívala si alternas sellos. Para un paladín de Reprensión con Sello de orden: mantiene activo Sello de Rectitud, cambia a Sello de orden de rango 1 en los últimos 0,4 segundos antes de un golpe y vuelve otra vez, Sentencia siempre que esté lista, Exorcismo y Cólera Sagrada contra no-muertos y demonios, Martillo de cólera, y Consagración con Venganza. Necesita mucho maná y buena sincronización. Los mismos recordatorios que la rotación integrada de Reprensión."
L["rm.forever.paladin.holy.Name"] = "Sagrado"
L["rm.forever.paladin.holy.Description"] = "Sanación de grupo una vez que Sagrado es tu árbol de talentos principal con 21 puntos (el nivel de Choque Sagrado), mientras Furia recta esté desactivada (aquí acaba también un Shockadin en grupo). Sana a tu objetivo amistoso actual: Choque Sagrado sobre un objetivo con tu Vigilia de la Luz, Vigilia de la Luz en combate, Limpiar o Purificar, Choque Sagrado en movimiento, Luz Sagrada con Infusión de Luz y Destello de Luz como sanación principal. Contra un enemigo: Sentencia de Luz cuando Sello de Luz está activo, Choque Sagrado, Vigilia de la Luz, Golpe Sagrado y Exorcismo. Recordatorios: Sello de Luz cuando no tienes sello, Favor divino en combate sobre un objetivo amistoso, tu aura y tu Bendición. En Forever la salud y el maná están ocultos para los addons, así que el objetivo que elijas es la única señal de quién necesita sanación; los Choques Sagrados de emergencia, las Luces Sagradas grandes e Imposición de manos quedan a tu criterio."
L["rm.forever.paladin.holy.wowhead.Name"] = "Sagrado, Choque Sagrado siempre que esté disponible (Wowhead)"
L["rm.forever.paladin.holy.wowhead.Description"] = "El estilo de sanación de Wowhead, una alternativa a la rotación integrada de Sagrado recomendada, desactivada de forma predeterminada: actívala y desactiva aquella, o aumenta su prioridad. Choque Sagrado como sanación habitual cada vez que esté disponible, disipaciones y Destello de Luz (la salud está oculta en Forever, así que usar Luz Sagrada para déficits grandes queda a tu criterio). Contra un enemigo mantiene tu Sentencia de Luz cambiando a Sello de Luz, juzgando y volviendo a Sello de Rectitud; después Golpe Sagrado, Exorcismo contra no-muertos y demonios, Choque Sagrado y Consagración. Los mismos recordatorios que la rotación integrada Sagrado."
L["rm.forever.paladin.protection.Name"] = "Protección (Wowhead)"
L["rm.forever.paladin.protection.Description"] = "Tanqueo, una vez que Protección es tu árbol de talentos principal o activas Furia recta. Cuando el objetivo lucha contra otro: Sentencia con Sello de furia (la provocación) y Sentencia veloz para reiniciarla. Con dos o más enemigos trabados en combate: Consagración, Exorcismo y Cólera Sagrada contra no-muertos y demonios, y Golpe Sagrado. Con un enemigo: Exorcismo contra no-muertos y demonios, Golpe Sagrado y Consagración. Recordatorios: Furia recta, Sello de furia, Sentencia cada vez que esté disponible, Escudo Sagrado mientras tanqueas, tu aura y tu Bendición. En Forever la salud y el maná están ocultos para los addons, así que Baluarte del templario e Imposición de manos quedan a tu criterio. Iniciar el combate, el posicionamiento y las demás provocaciones quedan a tu cargo."
L["rm.forever.paladin.protection.icyveins.Name"] = "Protección, primero Consagración (Icy Veins)"
L["rm.forever.paladin.protection.icyveins.Description"] = "El estilo de tanqueo de Icy Veins, una alternativa a la rotación integrada de Protección de Wowhead recomendada, desactivada de forma predeterminada: actívala y desactiva aquella, o aumenta su prioridad. Consagración primero siempre que puedas permitírtela, también contra un solo enemigo; Sentencia se reserva para provocar (sin recordatorio de usarla cada vez que esté disponible), con Sentencia veloz para reiniciarla; después Golpe Sagrado y Exorcismo contra no-muertos y demonios. Por lo demás, los mismos recordatorios de tanque."
L["rm.forever.paladin.retribution.Name"] = "Reprensión"
L["rm.forever.paladin.retribution.Description"] = "Reprensión y todo paladín cuerpo a cuerpo del nivel 1 al 60, y la opción predeterminada del paladín de Forever. Mantiene un sello de daño activo, renovado solo cuando le queda poco: Sello del cruzado juzgado una vez sobre un objetivo élite, después Sello de orden con un arma lenta (3,0 s) o, si no, Sello de Rectitud. Después Golpe Sagrado cada vez que esté disponible, Choque Sagrado y Vigilia de la Luz para un Shockadin, Exorcismo contra no-muertos y demonios, Consagración contra tres o más enemigos, Martillo de cólera cuando se puede lanzar, y cuerpo a cuerpo. Sentencia no activa el tiempo de reutilización global, así que es un recordatorio siempre que haya un sello activo. Otros recordatorios: tu aura y tu Bendición (Aura de reprensión y Reyes una vez aprendidas; se respetan las tuyas). Paso opcional, desactivado por defecto: Martillo de Justicia antes de una Sentencia con Sello de orden. En Forever el maná, la salud y el temporizador de golpes están ocultos para los addons, así que ahorrar maná, sanarte, Imposición de manos y la alternancia de sellos con Giro de la Luz quedan a tu criterio. Basada en guías de la beta de nivel 30."
L["rm.mop.paladin.holy.Name"] = "Recomendada"
L["rm.mop.paladin.holy.Description"] = "Para Sagrado, desde el nivel 10 en la especialización Sagrado. Con un aliado como objetivo, sana: con 3 de Poder Sagrado (o Propósito divino), Luz del alba cuando hay tres personas heridas cerca de ti; si no, Llama eterna sobre un objetivo que no la tenga; si no, Palabra de gloria; Choque Sagrado cada vez que esté disponible; Infusión de Luz en Radiancia Sagrada o Luz divina, y tres acumulaciones de Sanación desinteresada en Radiancia Sagrada o Destello de Luz; Destello de Luz por debajo del 35 %; Radiancia Sagrada para un grupo herido; Luz divina, y después Luz Sagrada para completar la salud. Con un enemigo como objetivo hace daño: Choque Sagrado, Sentencia, Golpe de cruzado, Prisma Sagrado, Sentencia de ejecución, Martillo de cólera, Acusar. Recordatorios: Sello de Perspicacia cuando hay otro sello activo (salvo Rectitud) o ninguno, bendiciones, Reprimenda, Señal de la Luz y Escudo Sagrado sobre tu foco (pon al tanque como foco), Súplica divina por debajo del 60 % de maná, Martillo de la Luz y tus tiempos de reutilización de sanación cuando tres personas están por debajo del 70 %, e Imposición de manos sobre un objetivo a punto de morir. Elegir a quién sanar, las disipaciones y la sanación con el puntero (mouseover) quedan a tu cargo."
L["rm.mop.paladin.protection.Name"] = "Recomendada"
L["rm.mop.paladin.protection.Description"] = "Recomendada para Protección, desde el nivel 10 en la especialización Protección. Inicia el combate con Escudo de vengador, y después Escudo de vengador con una activación de Gran cruzado, Escudo de vengador, Martillo de cólera, Golpe de cruzado, Sentencia, tu talento de nivel 90, Consagración, Cólera Sagrada y Escudo Sagrado. Con tres o más enemigos luchando contra ti cambia a Escudo de vengador, Consagración, Martillo del honrado, Sentencia y Cólera Sagrada. Escudo del honrado, Llama eterna y Palabra de gloria no activan el tiempo de reutilización global, así que se iluminan junto a la rotación: Escudo del honrado siempre que puedas permitírtelo, Llama eterna sobre ti cuando se está agotando con 3 de Poder Sagrado y tres acumulaciones de Bastión de gloria, y Palabra de gloria por debajo de la mitad de la salud sin ese talento. Otros recordatorios: Furia recta, Sello de Perspicacia cuando hay otro sello activo (salvo Rectitud) o ninguno, bendiciones, Reprimenda, Escudo Sagrado, Cólera vengativa y Vengador sagrado mientras tanqueas, y Guardián de los antiguos reyes, Defensor candente, Protección divina e Imposición de manos según tu salud. No puede ver el daño entrante, así que planifica tú las defensivas grandes."
L["rm.mop.paladin.protection.simulator.Name"] = "Acumular Poder Sagrado (simulador)"
L["rm.mop.paladin.protection.simulator.Description"] = "Una alternativa a la rotación integrada de Protección recomendada, desactivada por defecto: actívala y desactiva la otra, o súbele la prioridad. Sigue las listas de tanque del simulador: Escudo del honrado espera al Poder Sagrado lleno salvo que bajes del 40 % de salud o Propósito divino lo haga gratuito; Llama eterna justo antes de que desaparezca con más de dos acumulaciones de Bastión de gloria; Escudo Sagrado siempre activo; Vengador sagrado y Cólera vengativa cada vez que estén disponibles. Los generadores van en este orden: Golpe de cruzado, Sentencia, y después Escudo de vengador, Cólera Sagrada, el talento de nivel 90 y Martillo de cólera, con el mismo orden de área de efecto contra tres enemigos. Las defensivas sincronizadas con el jefe quedan a tu cargo."
L["rm.mop.paladin.retribution.Name"] = "Recomendada"
L["rm.mop.paladin.retribution.Description"] = "Recomendada para Reprensión, desde el nivel 10 en la especialización Reprensión. Mantiene Inquisición (lanzada con 3 de Poder Sagrado y renovada en sus últimos 3 segundos; desde el 81), gasta Veredicto del templario con el Poder Sagrado lleno o con una activación gratuita antes de generar más, y después Martillo de cólera, Golpe de cruzado, Sentencia y Exorcismo, y Veredicto del templario con 3 cuando no hay nada más listo. En Cólera vengativa gasta de inmediato y pone Sentencia por delante de Golpe de cruzado. Con dos o más enemigos luchando contra ti cambia a Tormenta divina, con Martillo del honrado cuando hay cuatro cerca. Inicia el combate a distancia con Sentencia o Exorcismo, y sugiere Palabra de gloria cuando estás en solitario y en peligro. Recordatorios: Sello de Verdad cuando hay otro sello activo o ninguno (se respeta Sello de Rectitud), Bendición de reyes o de poderío, Reprimenda, Cólera vengativa y Guardián de los antiguos reyes con Inquisición activa contra élites, Vengador sagrado durante las alas, Sentencia de ejecución y Martillo de la Luz, y Protección divina e Imposición de manos con poca salud. Sello de Rectitud contra grupos de enemigos y la elección de glifos quedan a tu cargo."
L["rm.mop.paladin.retribution.warcrafttavern.Name"] = "Primero Exorcismo (Warcraft Tavern)"
L["rm.mop.paladin.retribution.warcrafttavern.Description"] = "Una alternativa a la rotación integrada de Reprensión recomendada, desactivada por defecto: actívala y desactiva la otra, o súbele la prioridad. Primero va Exorcismo cada vez que esté disponible y con cada reinicio de El arte de la guerra; Inquisición se lanza con cualquier cantidad de Poder Sagrado cuando falta y se renueva con 3 en sus últimos 20 segundos; después, Golpe de cruzado, Sentencia, Veredicto del templario y Martillo de cólera (primero durante las alas con Cólera santificada). Contra dos o más enemigos usa Golpe de cruzado, Martillo de la Luz, Sentencia, Tormenta divina y Martillo de cólera. Cólera vengativa y Guardián de los antiguos reyes solo se sugieren contra élites. El Sello de Rectitud que la guía usa siempre que haya varios objetivos queda a tu cargo."
L["rm.mop.paladin.unspecialized.Name"] = "Antes de una especialización"
L["rm.mop.paladin.unspecialized.Description"] = "Para los niveles 1 a 9 y cualquier paladín que aún no haya elegido especialización; la rotación integrada de una especialización toma el relevo en cuanto eliges una. Inicia el combate a distancia con Sentencia, y después Golpe de cruzado y Sentencia, con Martillo de Justicia cuando estás en solitario y por debajo de la mitad de la salud, y Palabra de gloria por debajo del 40 %. Recordatorios: Sello de orden (Sello de Verdad desde el 24) cuando no lo tienes activo, Bendición de reyes, Reprimenda, y Destello de Luz fuera de combate cuando estás herido."
L["rm.retail.paladin.holy.Name"] = "Icy Veins"
L["rm.retail.paladin.holy.Description"] = "Sagrado en Midnight, como referencia: Rotation Master elige un hechizo, no un objetivo, y el juego oculta la salud de todos en combate, así que esta rotación sigue gastando tu Poder Sagrado y usando tus tiempos de reutilización sobre lo que tengas como objetivo, y deja a tu cargo decidir quién necesita sanación. El Poder Sagrado sigue visible en combate, así que se gasta primero con 5 y, después de tus demás sanaciones, con 3 o más. Sobre un objetivo amistoso: Llama eterna o Palabra de gloria con 5 de Poder Sagrado, Destello de Luz con Infusión de Luz, Choque Sagrado, Llama eterna o Palabra de gloria con 3 o más, Luz Sagrada, Destello de Luz; Luz del alba queda a tu cargo. Sobre un enemigo: Escudo del honrado con 5 de Poder Sagrado, Choque Sagrado, Escudo del honrado con 3 o más, Sentencia, Golpe de cruzado, Consagración. Recordatorios en combate: Tañido divino, Prisma Sagrado, Baluarte sagrado o Arma sagrada, Señal de virtud sobre un objetivo amistoso, Protección divina; un aura entre combates; Reprimenda. Imposición de manos queda a tu cargo. Cólera vengativa y Maestría de aura quedan a tu cargo."
L["rm.retail.paladin.initial.Name"] = "Asistente de combate de Blizzard"
L["rm.retail.paladin.initial.Description"] = "Recomendada antes de elegir una especialización (mientras el juego informa de la especialización inicial del paladín). Resalta el próximo hechizo que sugiere el Asistente de combate de Blizzard, el único consejo de rotación que el juego aún permite leer a un addon en el combate de Midnight; espera mientras lanzas o canalizas. Junto a él, los recordatorios que comparten todas las rotaciones integradas de paladín, cada uno una vez que conoces su hechizo. Cuando elijas una especialización al nivel 10, tomarán el relevo las rotaciones integradas de esa especialización."
L["rm.retail.paladin.protection.Name"] = "Asistente de combate de Blizzard"
L["rm.retail.paladin.protection.Description"] = "Recomendada para Protección en Midnight. Muestra la sugerencia del Asistente de combate de Blizzard, que ya incluye Escudo del honrado, Cólera vengativa y Centinela, y se detiene mientras lanzas o no tienes un enemigo como objetivo. Recordatorios de lo que deja fuera: un aura entre combates, Reprimenda ante un lanzamiento interrumpible, y Defensor candente y Guardián de los antiguos reyes siempre que estén disponibles en combate. La salud está oculta en Retail, así que decidir cuándo usarlos, y cuándo usar Imposición de manos, queda a tu criterio. Las provocaciones y el posicionamiento quedan a tu cargo."
L["rm.retail.paladin.protection.icyveins.Name"] = "De referencia (Icy Veins)"
L["rm.retail.paladin.protection.icyveins.Description"] = "Solo de referencia, desactivada por defecto: el orden de Icy Veins y SimulationCraft necesita los beneficios de Consagración, Vanguardia y Luz brillante, que Midnight oculta en combate. Consagración antes de iniciar el combate; después, Tañido divino, Martillo de Luz, Consagración cuando no estás dentro de ella, Escudo de vengador con Vanguardia, Escudo del honrado con 3 o más de Poder Sagrado, Martillo de cólera, Sentencia, Martillo bendito o Martillo del honrado, Escudo de vengador, Palabra de gloria con Luz brillante, Consagración. Recordatorios: Cólera vengativa o Centinela, Baluarte sagrado, Arma sagrada fuera de Cólera vengativa, defensivas, aura, Reprimenda."
L["rm.retail.paladin.protection.wowhead.Name"] = "Consagración como relleno, de referencia (Wowhead)"
L["rm.retail.paladin.protection.wowhead.Description"] = "Solo de referencia, desactivada por defecto: el orden de tanqueo de Wowhead. Sentencia cada vez que esté disponible, Escudo del honrado, Escudo de vengador, Tañido divino con 0 de Poder Sagrado, Martillo bendito o Martillo del honrado, y Consagración solo como relleno. La salud está oculta en Retail, así que Palabra de gloria por debajo de la mitad de la salud queda a tu cargo. Los mismos recordatorios que la referencia de Icy Veins."
L["rm.retail.paladin.retribution.Name"] = "Asistente de combate de Blizzard"
L["rm.retail.paladin.retribution.Description"] = "Recomendada para Reprensión en Midnight. En combate, el juego ahora oculta a los addons los beneficios, los perjuicios, los tiempos de reutilización y la salud, así que esta rotación muestra en tus barras de acción la propia sugerencia del Asistente de combate de Blizzard (la rotación de un solo botón), y se detiene mientras lanzas o no tienes un enemigo como objetivo. También te recuerda lo que esa sugerencia nunca cubre: un aura entre combates, Reprimenda ante un lanzamiento interrumpible y Protección divina siempre que esté disponible en combate. La salud está oculta en Retail, así que decidir cuándo usar Protección divina e Imposición de manos queda a tu criterio. Los abalorios y las habilidades raciales quedan a tu cargo."
L["rm.retail.paladin.retribution.icyveins.Name"] = "De referencia (Icy Veins)"
L["rm.retail.paladin.retribution.icyveins.Description"] = "Solo de referencia, desactivada por defecto: el orden de Icy Veins y SimulationCraft lee beneficios, cargas y números de enemigos que Midnight oculta en combate, así que no puede funcionar allí de forma fiable. Martillo de Luz; una habilidad de gasto gratuita con Propósito divino; con 5 de Poder Sagrado mientras Despertar de las cenizas se está recargando, la habilidad de gasto; Despertar de las cenizas; Tañido divino; Cuchilla de justicia con El arte de la guerra; Martillo de cólera antes de llegar al tope de cargas; con 3 o más de Poder Sagrado, Tormenta divina contra dos o más enemigos (o con Poder empíreo) y, si no, Veredicto final; Martillo de cólera; Cuchilla de justicia; Sentencia; Golpe de templario o Golpe de cruzado. El Poder Sagrado sigue visible en combate, así que sus puntos de gasto funcionan allí. Recordatorios: Cólera vengativa, Sentencia de ejecución con Despertar de las cenizas disponible, aura, Reprimenda, defensivas."
L["rm.sod.paladin.holy.Name"] = "Sagrado (SoD)"
L["rm.sod.paladin.holy.Description"] = "Sanación en grupo en Temporada de descubrimiento, elegida por tener grabada la runa Señal de la Luz, Luz divina o Escudo sacro, o por el árbol Sagrado sin Golpe de cruzado. Actúa sobre tu objetivo amistoso: Limpiar, Choque Sagrado en movimiento o por debajo del 30 %, Luz divina (Luz Sagrada con menos de la mitad del maná) por debajo del 60 % y Destello de Luz por debajo del 90 %. Con un enemigo al alcance cuerpo a cuerpo solo mantiene activo un sello. Recordatorios: Señal de la Luz y Escudo sacro sobre el objetivo que no los tenga, Aura de concentración o de devoción, Bendición de sabiduría, y Favor divino e Imposición de manos para un objetivo con muy poca salud. Las guías en que se basa son de la fase 4; elegir a quién sanar queda a tu cargo."
L["rm.sod.paladin.holy.wowhead.Name"] = "Sagrado, primero Luz Sagrada (SoD, Wowhead)"
L["rm.sod.paladin.holy.wowhead.Description"] = "El orden de sanación de la fase 4 de Wowhead para equipo con mucho crítico, una alternativa a la rotación integrada Sagrado de Temporada de descubrimiento recomendada, desactivada de forma predeterminada: actívala y desactiva aquella, o aumenta su prioridad. Luz divina o Luz Sagrada por debajo del 75 %, después Limpiar, Choque Sagrado para déficits pequeños o en movimiento, y Destello de Luz por debajo del 95 %. Los mismos recordatorios que la rotación integrada recomendada."
L["rm.sod.paladin.protection.Name"] = "Protección (SoD)"
L["rm.sod.paladin.protection.Description"] = "Tanqueo en Temporada de descubrimiento, elegida por Furia recta, por tener grabada la runa Martillo del honrado o Escudo de rectitud, o por el árbol de Protección. Sello de martirio, inicio del combate con Escudo Sagrado, Escudo de vengador y Exorcismo, y Escudo Sagrado siempre activo; contra un objetivo, Martillo del honrado, Escudo de rectitud, Exorcismo, Escudo de vengador, Sentencia, Tormenta divina, Consagración; con tres o más enemigos luchando contra ti, Martillo del honrado, Escudo de vengador, Consagración, Escudo de rectitud, Exorcismo. Recordatorios: Furia recta, Escudo Sagrado antes de iniciar el combate, Aura de devoción, Salvaguardia o Reyes, Cólera vengativa, Protección divina por debajo del 40 %, Imposición de manos, y Mano de expiación en grupo cuando tu objetivo ataca a otro."
L["rm.sod.paladin.protection.simulator.Name"] = "Protección (SoD, simulador)"
L["rm.sod.paladin.protection.simulator.Description"] = "La lista de tanque de simulador, una alternativa a la rotación integrada de Protección de Temporada de descubrimiento recomendada, desactivada de forma predeterminada: actívala y desactiva aquella, o aumenta su prioridad. Sentencia siempre que haya un sello activo, el sello renovado justo antes de que se agote, Escudo Sagrado, Escudo de vengador, Martillo del honrado, Exorcismo y, por último, Escudo de rectitud. Los mismos recordatorios que la rotación integrada recomendada."
L["rm.sod.paladin.retribution.Name"] = "Reprensión (SoD)"
L["rm.sod.paladin.retribution.Description"] = "Cuerpo a cuerpo en Temporada de descubrimiento del nivel 1 al 60, y allí la opción predeterminada para cualquier paladín. Mantiene activo Sello de martirio (Rectitud hasta que lo tengas), abre con Exorcismo, lanza Tormenta divina con tres de Poder Sagrado y después, según la velocidad del arma: con un arma de dos manos de 3,3 segundos o más lenta, Golpe de cruzado, Exorcismo, Tormenta divina y Sentencia; con una más rápida, Sentencia solo cuando el sello se agota, y después Exorcismo, Golpe de cruzado y Tormenta divina. Consagración con maná o con tres enemigos cercanos, Cólera Sagrada contra no-muertos y demonios (contra cualquier enemigo con Poder purificador grabado), Martillo de cólera con maná de sobra (siempre con Martillo de cólera mejorado grabado). Las runas se usan a medida que las grabas. Recordatorios: Aura de santidad, una Bendición, Cólera vengativa con Maestría en auras, una sanación entre combates y Escudo divino cuando estás a punto de morir."
L["rm.sod.paladin.retribution.icyveins.Name"] = "Reprensión (SoD, fase 4 de Icy Veins)"
L["rm.sod.paladin.retribution.icyveins.Description"] = "La lista anterior de la fase 4 de Icy Veins y Warcraft Tavern, también válida para subir de nivel, una alternativa a la rotación integrada de Reprensión de Temporada de descubrimiento recomendada, desactivada por defecto: actívala y desactiva la otra, o súbele la prioridad. Sentencia del cruzado una vez contra élites y en combates largos, Sello de martirio, Exorcismo, Golpe de cruzado, Tormenta divina y Sentencia cada vez que estén disponibles, Consagración con maná o con tres enemigos cercanos, y Martillo de cólera. Los mismos recordatorios que la rotación recomendada."
L["rm.sod.paladin.retribution.stacking.Name"] = "Reprensión, acumulación de sellos (SoD)"
L["rm.sod.paladin.retribution.stacking.Description"] = "Desactivada por defecto; actívala con la runa Alma del portador de sellos o con el conjunto de seis piezas que hace que los sellos perduren (Rotation Master no puede ver ninguno de los dos). Mantiene activos tanto Sello de orden como Sello de martirio, Tormenta divina con tres de Poder Sagrado, Golpe de cruzado, Exorcismo, Cólera Sagrada contra no-muertos y demonios (contra cualquier enemigo con Poder purificador grabado), Consagración, y Sentencia mientras ambos sellos estén activos."
L["rm.sod.paladin.retribution.twist.Name"] = "Reprensión, alternancia de sellos (SoD)"
L["rm.sod.paladin.retribution.twist.Description"] = "Desactivada por defecto; actívala si alternas sellos con un arma de dos manos lenta. Cambia entre Sello de martirio y Sello de orden en los últimos 0,4 segundos antes de cada golpe, no sugiere nada que active el tiempo de reutilización global en los 1,9 segundos previos, juzga mientras ambos sellos siguen activos y usa un relleno por golpe: Tormenta divina con tres de Poder Sagrado, Golpe de cruzado, Exorcismo. Necesita un temporizador de golpes y práctica."
L["rm.sod.paladin.shockadin.Name"] = "Shockadin (SoD, simulador)"
L["rm.sod.paladin.shockadin.Description"] = "Desactivada por defecto; actívala si haces daño con el árbol Sagrado. Se aplica con Sagrado como tu árbol principal y Conmoción y pavor grabado. Sello de martirio (si no, Rectitud), juzgado cuando se agota, Choque Sagrado para mantener Luz solar o con tres de Poder Sagrado, Exorcismo y Golpe de cruzado. Los mismos recordatorios que la rotación integrada de Reprensión de Temporada de descubrimiento."
L["rm.tbc.paladin.holy.Name"] = "Sagrado (Icy Veins y Wowhead)"
L["rm.tbc.paladin.holy.Description"] = "Sanación para un paladín Sagrado en grupo, sobre tu objetivo amistoso: Imposición de manos o Choque Sagrado para un objetivo a punto de morir, Limpiar (Purificar antes del 42), Choque Sagrado en movimiento, Luz Sagrada para daño fuerte, Luz Sagrada de rango 5 para mantener Gracia de Luz, y Destello de Luz en los demás casos. Con un objetivo hostil mantiene Sentencia de sabiduría. Recordatorios: Aura de concentración, Bendición de sabiduría, Iluminación divina y Favor divino. Un paladín Sagrado que juega en solitario recibe en su lugar una rotación integrada de Reprensión."
L["rm.tbc.paladin.holy.wowhead.Name"] = "Sagrado (sanación de tanques de Wowhead)"
L["rm.tbc.paladin.holy.wowhead.Description"] = "La sanación de tanques en banda de Wowhead, una alternativa a la rotación integrada de Sagrado recomendada, desactivada de forma predeterminada: actívala y desactiva aquella, o aumenta su prioridad. Luz Sagrada siempre que a tu objetivo le falte una décima parte de su salud, Destello de Luz solo para déficits pequeños, con las mismas emergencias, limpiezas, Sentencia y recordatorios que la rotación integrada Sagrado combinada."
L["rm.tbc.paladin.protection.icyveins.Name"] = "Protección (Icy Veins)"
L["rm.tbc.paladin.protection.icyveins.Description"] = "El tanqueo de Icy Veins, una alternativa a la rotación integrada de Protección de Wowhead recomendada, desactivada de forma predeterminada: actívala y desactiva aquella, o aumenta su prioridad. Sentencia del cruzado cuando nadie la mantiene, Rectitud (Sabiduría contra grupos de enemigos), Consagración como fuente principal de amenaza, Sentencia, Escudo Sagrado y después Escudo de vengador y Martillo de cólera cada vez que estén disponibles. Los mismos recordatorios que la variante de Wowhead, sin Cólera vengativa."
L["rm.tbc.paladin.protection.wowhead.Name"] = "Protección (Wowhead y simulador)"
L["rm.tbc.paladin.protection.wowhead.Description"] = "Tanqueo para el árbol de Protección o cualquier paladín con Furia recta activa. Inicia el combate con Escudo Sagrado, Escudo de vengador y Sentencia; contra un objetivo que asesta golpes aplastantes (jefe del mundo o tres o más niveles por encima de ti) Escudo Sagrado va primero; después Consagración, Exorcismo contra no-muertos y demonios, Sentencia, Escudo Sagrado, Cólera Sagrada contra grupos de no-muertos y Escudo de vengador salvo contra objetivos que asestan golpes aplastantes. Sello de sabiduría contra grupos de enemigos si falta maná; si no, Rectitud. Recordatorios: Furia recta, Aura de devoción, Salvaguardia (o Reyes, o Sabiduría), Cólera vengativa e Imposición de manos. Las provocaciones y los cambios de objetivo quedan a tu cargo."
L["rm.tbc.paladin.retribution.icyveins.Name"] = "Reprensión (Icy Veins)"
L["rm.tbc.paladin.retribution.icyveins.Description"] = "La Reprensión de Icy Veins, una alternativa a la rotación integrada de Reprensión de Wowhead recomendada, desactivada de forma predeterminada: actívala y desactiva aquella, o aumenta su prioridad. Sentencia del cruzado una vez por objetivo, Sello de Rectitud (Orden solo con un arma lenta; Sangre o Mártir en cuanto lo aprendas), Golpe de cruzado, Martillo de cólera y Sentencia cada vez que estén disponibles, Consagración contra dos o más enemigos, Exorcismo contra no-muertos y demonios, y Choque Sagrado para quienes suben de nivel como Sagrado. Los mismos recordatorios que la variante de Wowhead."
L["rm.tbc.paladin.retribution.twist.Name"] = "Reprensión con alternancia de sellos"
L["rm.tbc.paladin.retribution.twist.Description"] = "Desactivada por defecto; actívala si alternas sellos (nivel 64 o más, Sello de orden y Sangre o Mártir). Abre con Sentencia del cruzado y, en cada golpe, pone pronto Sello de orden (rango 1) y cambia a Sangre o Mártir en los últimos 0,4 segundos; Golpe de cruzado entre alternancias, solo juzga Sangre o Mártir, Exorcismo y Consagración solo como relleno, y por debajo del 12 % de maná mantiene Sangre sin alternar. Necesita un temporizador de golpes fiable; no tiene en cuenta la latencia."
L["rm.tbc.paladin.retribution.wowhead.Name"] = "Reprensión (Wowhead y simulador)"
L["rm.tbc.paladin.retribution.wowhead.Description"] = "Reprensión cuerpo a cuerpo del nivel 1 al 70, y la opción predeterminada para cualquier paladín al que no se ajuste ninguna otra rotación integrada. Abre contra cada objetivo con Sentencia de sabiduría (con poco maná) o la del cruzado, mantiene activo tu mejor sello (Sangre o Mártir, Orden y luego Rectitud), Golpe de cruzado, solo juzga Rectitud, Sangre o Mártir (u Orden sobre un objetivo aturdido), Exorcismo contra no-muertos y demonios, y Consagración contra tres o más enemigos si te sobra maná. Martillo de cólera queda a tu cargo (Wowhead solo lo usa contra objetivos que huyen). Recordatorios: Aura de santidad, de reprensión o de devoción, una Bendición sobre ti mismo, una sanación tras el combate y Cólera vengativa. La alternancia de sellos es otra rotación integrada."
